// @relation(AC-SVR-ADDRSP-255-URI-NAMESPACE, scope=function)
TEST(InstantiateObjectNsiTests, ConcurrentDirectUriEntriesAllUseTheRegisteredUriNamespace)
{
  constexpr std::size_t entryCount{8u};
  boost::asio::thread_pool threadPool{entryCount};
  const auto cfg = ApplicationConfig::load_default();
  const auto limits = make_encoding_limits(cfg);

  auto addressSpace = AddressSpace::create("uri:test", threadPool.get_executor());
  StructureFactory structureFactory;
  load_ns0(limits, addressSpace, structureFactory);
  const auto dictionaryIndex = addressSpace.add_namespace_sync(
    default_ns::Namespace::create(uriDictionaryNamespaceUri, threadPool.get_executor()));
  const auto namespacesBefore = addressSpace.namespace_array().get_namespace_array().size();
  InstantiationService inst{addressSpace};
  const InstantiationOptions options{};

  std::barrier startLine{entryCount};
  std::vector<std::future<NodeSubtreeResult>> futures;
  futures.reserve(entryCount);
  for (std::size_t index = 0; index < entryCount; ++index)
  {
    futures.push_back(std::async(std::launch::async,
      [&, index]
      {
        const auto identifier = fmt::format("http://example.org/dictionary/2026#Entry{}", index);
        startLine.arrive_and_wait();
        return run_instantiate_object(inst,
          NodeId{ObjectId::ObjectsFolder},
          QualifiedName{1u, identifier},
          NodeId{ObjectTypeId::UriDictionaryEntryType},
          options);
      }));
  }

  for (std::size_t index = 0; index < entryCount; ++index)
  {
    auto result = futures[index].get();
    ASSERT_TRUE(result.is_good()) << "entry " << index << " failed with " << result.status_code().as_uint32();
    EXPECT_EQ(std::move(result).value().root().namespace_index(), dictionaryIndex);
  }
  EXPECT_EQ(addressSpace.namespace_array().get_namespace_array().size(), namespacesBefore)
    << "instantiation must not register a namespace";

  ::ua::test_utils::drain_with_timeout(threadPool);
}

// Part 3 section 5.2.4: a child's BrowseName is copied from the type declaration and
// does NOT follow the NodeId NSI. FileType's children are declared as 0:Open,
// 0:Close, ... - the instance children keep BrowseName NSI 0 even though their
// NodeIds are allocated in NSI 1.
TEST(InstantiateObjectNsiTests, ChildBrowseNameNsiDoesNotFollowNodeIdNsi)
{
  boost::asio::thread_pool threadPool;
  const auto cfg = ApplicationConfig::load_default();
  const auto limits = make_encoding_limits(cfg);

  auto addressSpace = AddressSpace::create("uri:test", threadPool.get_executor());
  StructureFactory structureFactory;
  load_ns0(limits, addressSpace, structureFactory);

  InstantiationService inst{addressSpace};

  const NodeId parent{ObjectId::ObjectsFolder};  // NSI 0
  InstantiationOptions options{};
  auto result =
    run_instantiate_object(inst, parent, QualifiedName{1, "MyFile"}, NodeId{ObjectTypeId::FileType}, options);
  ASSERT_TRUE(result.is_good()) << result.status_code().as_uint32();

  auto subtree = std::move(result).value();
  const NodeId childId = [&]
  {
    auto children = hierarchical_children(addressSpace, subtree.root());
    EXPECT_TRUE(children.contains("Open"));
    return children.at("Open");
  }();

  // The NodeId landed in NSI 1 (fallback) ...
  EXPECT_EQ(childId.namespace_index(), 1u);

  // ... but the BrowseName is copied verbatim from the 0:Open declaration.
  auto childResult = addressSpace.try_find_node_sync(childId);
  ASSERT_TRUE(childResult.is_good());
  const auto browseName = childResult.value().get_browse_name();
  EXPECT_EQ(browseName.namespace_index(), 0u)
    << "BrowseName must stay in the declaration's NSI, not follow the NodeId NSI";
  EXPECT_EQ(browseName.name(), "Open");

  ::ua::test_utils::drain_with_timeout(threadPool);
}

