// Part 3 section 4.9.2, "Rules for applying Interfaces": when an ObjectType references an Interface with a
// HasInterface Reference, "Each mandatory InstanceDeclaration of the fully-inherited
// InstanceDeclarationHierarchy of the Interface shall have for each BrowsePath a similar Node with
// the ModellingRule Mandatory using the same BrowsePath in the fully-inherited
// InstanceDeclarationHierarchy of the ObjectType. **The rules for instantiating InstanceDeclarations
// defined in 6.2.6 shall be applied.**"
//
// Read that carefully, because it is easy to read backwards. The obligation is on the *type author*:
// applying an Interface means mirroring its mandatory declarations onto the ObjectType's own
// hierarchy, and what instantiation then sees is an ordinary declaration on an ordinary type. It is
// NOT a rule that the instantiation engine must chase HasInterface and pull members across - which
// matters here, because this engine's declaration walk follows HasComponent, HasProperty and
// HasOrderedComponent forward and the HasSubtype chain upward, and follows HasInterface nowhere.
// That is conforming, and the shape below is what makes it so.
//
// So what is testable, and what this drives, is the consequence the clause states: an
// Interface-supplied member reaches the instance *by the same path and the same rule* as a member the
// type declared on its own account. The control is deliberately inside the test - one Mandatory
// member mirrored from the Interface, one Mandatory member native to the type - because "exactly as
// the type's own are" is a comparison, and a test asserting only the Interface member would pass on
// an engine that had quietly stopped instantiating anything at all.
// @verifies AC-SVR-ADDRSP-028-INTERFACE-NODES-AS-TYPE
TEST(InstantiateObjectInterfaceTests, AnInterfaceSuppliedMemberIsInstantiatedExactlyAsTheTypesOwnIs)
{
  boost::asio::thread_pool threadPool;
  const auto cfg = ApplicationConfig::load_default();
  const auto limits = make_encoding_limits(cfg);

  auto addressSpace = AddressSpace::create("uri:test", threadPool.get_executor());
  StructureFactory structureFactory;
  load_ns0(limits, addressSpace, structureFactory);

  const auto make = [&](const NodeId& id, NodeClass nodeClass, uint16_t nameNs, std::string_view name)
  {
    auto created = addressSpace.try_create_node_sync(id, nodeClass, {});
    EXPECT_TRUE(created.is_good()) << "could not create " << ua::to_string(id);
    auto node = created.value();
    node.set_browse_name(QualifiedName{nameNs, name});
    node.set_display_name(LocalizedText{"", String{name}});
    return node;
  };

  // A mandatory Variable InstanceDeclaration, wired under `owner` with its ModellingRule.
  const auto declareMandatoryVariable = [&](const NodeId& owner, const NodeId& declId, std::string_view name)
  {
    auto decl = make(declId, NodeClass::Variable, 1u, name);
    auto variable = decl.as<VariableAccessor>();
    EXPECT_TRUE(variable.has_value());
    variable->set_data_type(NodeId{DataTypeId::String});
    variable->set_value_rank(ValueRank{ValueRank::scalar});
    variable->set_access_level(AccessLevelType{0u});
    addressSpace.try_find_node_sync(owner).value().try_add_reference_sync(
      NodeId{ReferenceTypeId::HasProperty}, declId);
    decl.try_add_reference_sync(
      NodeId{ReferenceTypeId::HasModellingRule}, NodeId{ObjectId::ModellingRule_Mandatory});
  };

  // The Interface: an abstract subtype of BaseInterfaceType declaring one mandatory member.
  const NodeId interfaceTypeId{1u, "ITestLocationType"};
  auto interfaceType = make(interfaceTypeId, NodeClass::ObjectType, 1u, "ITestLocationType");
  if (auto asType = interfaceType.as<ObjectTypeAccessor>())
    asType->set_is_abstract(true);
  addressSpace.try_find_node_sync(NodeId{ObjectTypeId::BaseInterfaceType})
    .value()
    .try_add_reference_sync(NodeId{ReferenceTypeId::HasSubtype}, interfaceTypeId);
  declareMandatoryVariable(interfaceTypeId, NodeId{1u, "ITestLocationType.Location"}, "Location");

  // The concrete type: applies the Interface, mirrors its mandatory member onto its own hierarchy as
  // section 4.9.2 requires, and declares one member of its own as the control.
  const NodeId deviceTypeId{1u, "TaggedDeviceType"};
  make(deviceTypeId, NodeClass::ObjectType, 1u, "TaggedDeviceType");
  addressSpace.try_find_node_sync(NodeId{ObjectTypeId::BaseObjectType})
    .value()
    .try_add_reference_sync(NodeId{ReferenceTypeId::HasSubtype}, deviceTypeId);
  addressSpace.try_find_node_sync(deviceTypeId)
    .value()
    .try_add_reference_sync(NodeId{ReferenceTypeId::HasInterface}, interfaceTypeId);
  declareMandatoryVariable(deviceTypeId, NodeId{1u, "TaggedDeviceType.Location"}, "Location");
  declareMandatoryVariable(deviceTypeId, NodeId{1u, "TaggedDeviceType.SerialNumber"}, "SerialNumber");

  InstantiationService inst{addressSpace};
  InstantiationOptions options{};
  auto result = run_instantiate_object(
    inst, NodeId{ObjectId::ObjectsFolder}, QualifiedName{1, "Device1"}, deviceTypeId, options);
  ASSERT_TRUE(result.is_good()) << "instantiating a type that applies an Interface failed: "
                                << result.status_code().as_uint32();

  auto subtree = std::move(result).value();
  auto children = hierarchical_children(addressSpace, subtree.root());

  ASSERT_TRUE(children.contains("SerialNumber"))
    << "the type's own Mandatory member is missing, so the comparison this test makes has no control "
       "and nothing below would mean anything";
  ASSERT_TRUE(children.contains("Location"))
    << "the Interface-supplied Mandatory member is missing from the instance. An instance whose "
       "Interface members were not materialised satisfies the type-level rule and gives a Client "
       "nothing at the instance, which is what makes an Interface documentation rather than a "
       "contract";

  // "Exactly as the type's own are": same treatment, not merely present.
  EXPECT_EQ(children.at("Location").namespace_index(), children.at("SerialNumber").namespace_index())
    << "the Interface-supplied member landed in a different namespace from the type's own member, so "
       "the two were not instantiated by the same rule";

  auto location = addressSpace.try_find_node_sync(children.at("Location"));
  auto serial = addressSpace.try_find_node_sync(children.at("SerialNumber"));
  ASSERT_TRUE(location.is_good());
  ASSERT_TRUE(serial.is_good());
  EXPECT_EQ(location.value().get_node_class(), serial.value().get_node_class())
    << "the two members were instantiated into different NodeClasses";
  EXPECT_EQ(
    location.value().get_browse_name().namespace_index(), serial.value().get_browse_name().namespace_index())
    << "the BrowseName namespaces differ, so the declaration copy took a different path for the "
       "Interface-supplied member";

  ::ua::test_utils::drain_with_timeout(threadPool);
}

// Part 3 section 6.4.3 requires parallel References that are reproduced from one directly connected
// InstanceDeclaration pair to connect the same derived Nodes. Part 3 section 6.4.4.4.2 separately permits
// NonHierarchical declaration References to be omitted, so zero copied edges is a conforming policy;
// one copied edge or two edges with different derived targets is not.
// @relation(AC-SVR-ADDRSP-145-FANOUT-CONNECTS-SAME-NODES, scope=function)
TEST(InstantiationParallelReferenceTests,
  NonHierarchicalParallelDeclarationReferencesAreEitherOmittedOrShareOneDerivedTarget)
{
  boost::asio::thread_pool threadPool;
  const auto cfg = ApplicationConfig::load_default();
  const auto limits = make_encoding_limits(cfg);

  auto addressSpace = AddressSpace::create("uri:test", threadPool.get_executor());
  StructureFactory structureFactory;
  load_ns0(limits, addressSpace, structureFactory);

  const auto make = [&](const NodeId& id, NodeClass nodeClass, std::string_view name)
  {
    auto created = addressSpace.try_create_node_sync(id, nodeClass, {});
    EXPECT_TRUE(created.is_good()) << "could not create " << ua::to_string(id);
    auto node = std::move(created).value();
    node.set_browse_name(QualifiedName{1u, name});
    node.set_display_name(LocalizedText{"", String{name}});
    return node;
  };

  const NodeId firstReferenceType{1u, "ParallelConnectionA"};
  const NodeId secondReferenceType{1u, "ParallelConnectionB"};
  auto firstType = make(firstReferenceType, NodeClass::ReferenceType, "ParallelConnectionA");
  auto secondType = make(secondReferenceType, NodeClass::ReferenceType, "ParallelConnectionB");
  for (auto* referenceType : {&firstType, &secondType})
  {
    auto accessor = referenceType->as<ReferenceTypeAccessor>();
    ASSERT_TRUE(accessor.has_value());
    accessor->set_is_abstract(false);
    accessor->set_symmetric(false);
    accessor->set_inverse_name(LocalizedText{"", "IsParallelConnectionOf"});
  }
  auto nonHierarchicalReferences =
    addressSpace.try_find_node_sync(NodeId{ReferenceTypeId::NonHierarchicalReferences});
  ASSERT_TRUE(nonHierarchicalReferences.is_good());
  ASSERT_TRUE(nonHierarchicalReferences.value()
                .try_add_reference_sync(NodeId{ReferenceTypeId::HasSubtype}, firstReferenceType)
                .is_good());
  ASSERT_TRUE(nonHierarchicalReferences.value()
                .try_add_reference_sync(NodeId{ReferenceTypeId::HasSubtype}, secondReferenceType)
                .is_good());

  const NodeId typeId{1u, "ParallelDeclarationType"};
  auto type = make(typeId, NodeClass::ObjectType, "ParallelDeclarationType");
  auto objectType = type.as<ObjectTypeAccessor>();
  ASSERT_TRUE(objectType.has_value());
  objectType->set_is_abstract(false);
  ASSERT_TRUE(addressSpace.try_find_node_sync(NodeId{ObjectTypeId::BaseObjectType})
                .value()
                .try_add_reference_sync(NodeId{ReferenceTypeId::HasSubtype}, typeId)
                .is_good());

  const NodeId declarationAId{1u, "ParallelDeclarationType.A"};
  const NodeId declarationBId{1u, "ParallelDeclarationType.B"};
  auto declarationA = make(declarationAId, NodeClass::Variable, "A");
  auto declarationB = make(declarationBId, NodeClass::Variable, "B");
  for (auto* declaration : {&declarationA, &declarationB})
  {
    auto variable = declaration->as<VariableAccessor>();
    ASSERT_TRUE(variable.has_value());
    variable->set_data_type(NodeId{DataTypeId::String});
    variable->set_value_rank(ValueRank{ValueRank::scalar});
    variable->set_access_level(AccessLevelType{0u});
    ASSERT_TRUE(declaration
                  ->try_add_reference_sync(
                    NodeId{ReferenceTypeId::HasModellingRule}, NodeId{ObjectId::ModellingRule_Mandatory})
                  .is_good());
  }
  ASSERT_TRUE(type.try_add_reference_sync(NodeId{ReferenceTypeId::HasProperty}, declarationAId).is_good());
  ASSERT_TRUE(type.try_add_reference_sync(NodeId{ReferenceTypeId::HasProperty}, declarationBId).is_good());
  ASSERT_TRUE(declarationA.try_add_reference_sync(firstReferenceType, declarationBId).is_good());
  ASSERT_TRUE(declarationA.try_add_reference_sync(secondReferenceType, declarationBId).is_good());

  size_t declarationParallelReferenceCount = 0;
  for (const auto& reference : declarationA.get_references_sync())
  {
    if (reference.is_forward() && !reference.is_remote() &&
        reference.target_id() == ExpandedNodeId{declarationBId} &&
        (reference.type_id() == firstReferenceType || reference.type_id() == secondReferenceType))
    {
      ++declarationParallelReferenceCount;
    }
  }
  ASSERT_EQ(declarationParallelReferenceCount, 2u)
    << "the type fixture must directly connect the same declaration pair with both ReferenceTypes";

  InstantiationService instantiationService{addressSpace};
  InstantiationOptions options{};
  auto result = run_instantiate_object(instantiationService,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{1u, "ParallelInstance"},
    typeId,
    options);
  ASSERT_TRUE(result.is_good()) << result.status_code().as_uint32();

  auto subtree = std::move(result).value();
  const auto children = hierarchical_children(addressSpace, subtree.root());
  ASSERT_TRUE(children.contains("A"));
  ASSERT_TRUE(children.contains("B"));
  const NodeId derivedAId = children.at("A");
  const NodeId derivedBId = children.at("B");

  struct LogicalReference
  {
    NodeId type;
    NodeId source;
    NodeId target;
  };

  std::vector<LogicalReference> reproduced;
  const auto collect = [&](const NodeId& holderId)
  {
    auto holder = addressSpace.try_find_node_sync(holderId);
    ASSERT_TRUE(holder.is_good());
    for (const auto& reference : holder.value().get_references_sync())
    {
      if (reference.is_remote() ||
          (reference.type_id() != firstReferenceType && reference.type_id() != secondReferenceType))
      {
        continue;
      }
      const NodeId otherId = reference.target_id().node_id();
      LogicalReference logical{reference.type_id(),
        reference.is_forward() ? holderId : otherId,
        reference.is_forward() ? otherId : holderId};
      bool alreadyCollected = false;
      for (const auto& existing : reproduced)
      {
        if (existing.type == logical.type && existing.source == logical.source &&
            existing.target == logical.target)
        {
          alreadyCollected = true;
          break;
        }
      }
      if (!alreadyCollected)
        reproduced.push_back(std::move(logical));
    }
  };
  collect(derivedAId);
  collect(derivedBId);

  if (!reproduced.empty())
  {
    EXPECT_EQ(reproduced.size(), 2u)
      << "copying only one parallel declaration Reference creates a partial instance relation";
    for (const auto& expectedType : {firstReferenceType, secondReferenceType})
    {
      size_t matchingTypeCount = 0;
      for (const auto& reference : reproduced)
      {
        if (reference.type != expectedType)
          continue;
        ++matchingTypeCount;
        EXPECT_EQ(reference.source, derivedAId);
        EXPECT_EQ(reference.target, derivedBId)
          << "parallel declaration References were split across different derived targets";
      }
      EXPECT_EQ(matchingTypeCount, 1u);
    }
  }

  ::ua::test_utils::drain_with_timeout(threadPool);
}

// -- Partial VariableInstantiationAttributes: supplied fields override, omitted fields
//    inherit (ua_instantiation_options.h) ---------------------------------------------
//
// This used to be all-or-nothing: supplying ANY of the three attributes skipped the
// type-definition lookup entirely, so every field left nullopt inherited NOTHING. The
// instance was created with no DataType at all - an attribute Part 3 5.6.2 makes mandatory
// on a Variable - and VariableAccessor::get_data_type() then threw a bare Variant access
// error on the empty attribute.

// @relation(AC-COMP-SDK-POST-VARIABLE-ATTRIBUTES, scope=function)
TEST(InstantiateVariableAttributeTests, OmittedDataTypeInheritsWhenAnotherAttributeIsSupplied)
{
  boost::asio::thread_pool threadPool;
  const auto cfg = ApplicationConfig::load_default();
  const auto limits = make_encoding_limits(cfg);

  auto addressSpace = AddressSpace::create("uri:test", threadPool.get_executor());
  StructureFactory structureFactory;
  load_ns0(limits, addressSpace, structureFactory);

  InstantiationService inst{addressSpace};

  // ValueRank and AccessLevel supplied, DataType deliberately omitted.
  VariableInstantiationAttributes attributes;
  attributes.valueRank = ValueRank::scalar;
  attributes.accessLevel = AccessLevelType{AccessLevelType::Bit::CurrentRead};
  attributes.dataType = std::nullopt;

  const InstantiationOptions options{};
  auto result = run_instantiate_variable(inst,
    NodeId{ObjectId::ObjectsFolder},
    QualifiedName{1, "PartiallySpecified"},
    NodeId{VariableTypeId::BaseDataVariableType},
    options,
    attributes);
  ASSERT_TRUE(result.is_good()) << result.status_code().as_uint32();
  auto subtree = std::move(result).value();

  auto found = addressSpace.try_find_sync<VariableAccessor>(subtree.root());
  ASSERT_TRUE(found.is_good()) << found.status_code().as_uint32();
  const VariableAccessor& variable = found.value();

  // Reading it must not throw: the attribute has to BE there, per Part 3 5.6.2.
  NodeId dataType;
  ASSERT_NO_THROW(dataType = variable.get_data_type())
    << "DataType was left unset, so reading the mandatory attribute threw";
  EXPECT_EQ(dataType, NodeId{DataTypeId::BaseDataType})
    << "omitted DataType must inherit BaseDataVariableType's BaseDataType";

  // The supplied fields still win.
  EXPECT_EQ(variable.get_value_rank().as_int32(), ValueRank::scalar);
  EXPECT_TRUE(variable.get_access_level().test(AccessLevelType::Bit::CurrentRead));

  ::ua::test_utils::drain_with_timeout(threadPool);
}

